import { z } from 'zod';
import type { Point } from '../../types';

const dollars = z.coerce.number().min(0).max(1);

const MarketSchema = z.object({
  ticker: z.string(),
  yes_sub_title: z.string().optional(),
  yes_bid_dollars: dollars.optional(),
  yes_ask_dollars: dollars.optional(),
  last_price_dollars: dollars.optional(),
});

const EventsSchema = z.object({
  events: z.array(z.object({ event_ticker: z.string(), markets: z.array(MarketSchema).default([]) })),
});

export interface KalshiMarket {
  ticker: string;
  label: string;
  /** Bid/ask midpoint; falls back to last trade when the book is one-sided. */
  p: number;
}

/** Bid/ask midpoint, ignoring empty books (bid 0 / ask 1). */
export function midpoint(bid?: number, ask?: number, last?: number): number | null {
  const hasBid = bid !== undefined && bid > 0;
  const hasAsk = ask !== undefined && ask > 0 && ask < 1;
  if (hasBid && hasAsk) return round((bid + ask) / 2);
  if (last !== undefined && last > 0) return last;
  return null;
}

/** Parses `/events?series_ticker=…&with_nested_markets=true` into markets grouped by event ticker. */
export function parseKalshiEvents(json: unknown): Map<string, KalshiMarket[]> {
  const out = new Map<string, KalshiMarket[]>();
  for (const event of EventsSchema.parse(json).events) {
    out.set(
      event.event_ticker,
      event.markets.flatMap((m) => {
        const p = midpoint(m.yes_bid_dollars, m.yes_ask_dollars, m.last_price_dollars);
        return p === null ? [] : [{ ticker: m.ticker, label: m.yes_sub_title ?? m.ticker, p }];
      }),
    );
  }
  return out;
}

/** Returns the markets of a single event from an events response. */
export function parseKalshiEvent(json: unknown, eventTicker: string): KalshiMarket[] {
  const markets = parseKalshiEvents(json).get(eventTicker);
  if (!markets) throw new Error(`event ${eventTicker} not found`);
  return markets;
}

export function findByTickerSuffix(markets: KalshiMarket[], suffix: string): KalshiMarket | undefined {
  return markets.find((m) => m.ticker.endsWith(suffix));
}

const CandleSchema = z.object({
  candlesticks: z.array(
    z.object({
      end_period_ts: z.number(),
      price: z.object({ close_dollars: dollars.optional() }).default({}),
      yes_bid: z.object({ close_dollars: dollars.optional() }).optional(),
      yes_ask: z.object({ close_dollars: dollars.optional() }).optional(),
    }),
  ),
});

/** Parses daily candlesticks; uses close price, or bid/ask mid on days without trades. */
export function parseKalshiCandles(json: unknown): Point[] {
  return CandleSchema.parse(json).candlesticks.flatMap((c) => {
    const p = c.price.close_dollars ?? midpoint(c.yes_bid?.close_dollars, c.yes_ask?.close_dollars);
    return p === null || p === undefined ? [] : [{ t: c.end_period_ts, p }];
  });
}

function round(x: number): number {
  return Math.round(x * 10000) / 10000;
}
